package kome.common.network;
import cpw.mods.fml.common.network.simpleimpl.*;import io.netty.buffer.ByteBuf;import kome.common.KOMEReflection;import kome.common.data.*;import lotr.common.entity.npc.LOTREntityNPC;import net.minecraft.entity.Entity;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.util.ChatComponentText;
public class KOMEPacketRelationshipAction implements IMessage {public static final int MASTER=0,LIEGE=1,TALK=0,SERVICE=1;public int entityId,relationship,action;public KOMEPacketRelationshipAction(){}public KOMEPacketRelationshipAction(int i,int r,int a){entityId=i;relationship=r;action=a;}public void fromBytes(ByteBuf b){entityId=b.readInt();relationship=b.readByte();action=b.readByte();}public void toBytes(ByteBuf b){b.writeInt(entityId);b.writeByte(relationship);b.writeByte(action);}public static void sendHub(EntityPlayerMP p,LOTREntityNPC n,int r){KOMEPacketHandler.network.sendTo(new KOMEPacketRelationshipHub(n.getEntityId(),r,n.getNPCName(),n.getFaction()==null?"":n.getFaction().factionName()),p);}public static class Handler implements IMessageHandler<KOMEPacketRelationshipAction,IMessage>{public IMessage onMessage(KOMEPacketRelationshipAction m,MessageContext c){EntityPlayerMP p=c.getServerHandler().playerEntity;Entity e=KOMEReflection.getWorld(p).getEntityByID(m.entityId);if(!(e instanceof LOTREntityNPC)||!e.isEntityAlive()||p.getDistanceSqToEntity(e)>64){p.addChatMessage(new ChatComponentText("That relationship NPC is no longer available."));return null;}LOTREntityNPC n=(LOTREntityNPC)e;KOMESerfKnightProgression s=KOMEWorldData.get(p.worldObj).getProgression(KOMEReflection.getEntityUUID(p)).getSerfKnightProgression();boolean exact=m.relationship==MASTER?s.getSerfdomMaster().hasSameIdentity(KOMEProgressionNpcRankService.referenceOf(n)):s.getProspectiveLiege().hasSameIdentity(KOMEProgressionNpcRankService.referenceOf(n));if(!exact){p.addChatMessage(new ChatComponentText("That is not your current relationship NPC."));return null;}if(m.action==TALK){n.interactFirst(p);return null;}if(m.relationship==MASTER){KOMEPacketSerfdomMasterAction.sendMenu(p,n);return null;}KOMEProgressionNpcSpeech.say(p,n,KOMESerfKnightService.mayIssueAssignment(s,KOMESerfKnightService.calendarDayNow())?"You are in my service now. When I have a task fit to test you, I will give it.":"You have done enough for one day. Return when I have work for you.");return null;}}}
